DECLARE
  counter NUMBER DEFAULT 0;
BEGIN
  WHILE (counter < 3) DO
    counter := counter + 1;
  END WHILE;
  WHILE (counter < 5) LOOP
    counter := counter + 1;
  END LOOP;
  REPEAT
    counter := counter + 10;
  UNTIL (counter > 30)
  END REPEAT;
  RETURN counter;
END;

DECLARE
  counter NUMBER DEFAULT 0;
  skipped NUMBER DEFAULT 0;
BEGIN
  LOOP
    counter := counter + 1;
    IF (counter > 6) THEN
      BREAK;
    END IF;
    IF (counter = 2) THEN
      CONTINUE;
    END IF;
    IF (counter = 4) THEN
      ITERATE;
    END IF;
    skipped := skipped + 1;
  END LOOP;
  LOOP
    EXIT;
  END LOOP;
  RETURN counter * 100 + skipped;
END;

DECLARE
  hits NUMBER DEFAULT 0;
BEGIN
  FOR outer_index IN 1 TO 3 DO
    FOR inner_index IN 1 TO 3 DO
      hits := hits + 1;
      IF (inner_index = 2) THEN
        CONTINUE outer_loop;
      END IF;
      IF (outer_index = 3) THEN
        BREAK outer_loop;
      END IF;
    END FOR inner_loop;
  END FOR outer_loop;
  RETURN hits;
END;

